$aLookup[] = array(form_itens_proc_compra_pack_protect_string('1') => str_replace('<', '&lt;',form_itens_proc_compra_pack_protect_string("Sim")));
$aLookup[] = array(form_itens_proc_compra_pack_protect_string('0') => str_replace('<', '&lt;',form_itens_proc_compra_pack_protect_string("Não")));
