$_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['Lookup_ind_distr_custo'][] = '0';
          $aLookupOrig = $aLookup;
          $sSelComp = "name=\"ind_distr_custo\"";
          if (isset($this->NM_ajax_info['select_html']['ind_distr_custo']) && !empty($this->NM_ajax_info['select_html']['ind_distr_custo']))
          {
              $sSelComp = str_replace('{SC_100PERC_CLASS_INPUT}', $this->classes_100perc_fields['input'], $this->NM_ajax_info['select_html']['ind_distr_custo']);
          }
          $sLookup = '';
          if (empty($aLookup))
          {
              $aLookup[] = array('' => '');
          }
          foreach ($aLookup as $aOption)
          {
              foreach ($aOption as $sValue => $sLabel)
              {

                  if ($this->ind_distr_custo == $sValue)
                  {
                      $this->_tmp_lookup_ind_distr_custo = $sLabel;
                  }

                  $sOpt     = ($sValue !== $sLabel) ? $sValue : $sLabel;
                  $sLookup .= "<option value=\"" . $sOpt . "\">" . $sLabel . "</option>";
              }
          }
          $aLookup  = $sLookup;
          $this->NM_ajax_info['fldList']['ind_distr_custo'] = array(
                       'row'    => '',
               'type'    => 'select',
               'valList' => array($sTmpValue),
              );
          $aLabel     = array();
          $aLabelTemp = array();
          foreach ($this->NM_ajax_info['fldList']['ind_distr_custo']['valList'] as $i => $v)
          {
              $this->NM_ajax_info['fldList']['ind_distr_custo']['valList'][$i] = form_itens_proc_compra_pack_protect_string($v);
          }
          foreach ($aLookupOrig as $aValData)
          {
              if (in_array(key($aValData), $this->NM_ajax_info['fldList']['ind_distr_custo']['valList']))
              {
                  $aLabelTemp[key($aValData)] = current($aValData);
              }
          }
          foreach ($this->NM_ajax_info['fldList']['ind_distr_custo']['valList'] as $iIndex => $sValue)
          {
              $aLabel[$iIndex] = (isset($aLabelTemp[$sValue])) ? $aLabelTemp[$sValue] : $sValue;
          }
          $this->NM_ajax_info['fldList']['ind_distr_custo']['labList'] = $aLabel;
          }
   }

