      $this->qt_comprada = str_replace($sc_parm1, $sc_parm2, $this->qt_comprada); 
      $this->vl_cubagem = str_replace($sc_parm1, $sc_parm2, $this->vl_cubagem); 
      $this->calc_gm = str_replace($sc_parm1, $sc_parm2, $this->calc_gm); 
      $this->vl_negociado = str_replace($sc_parm1, $sc_parm2, $this->vl_negociado); 
