   function nm_db_retorna($str_where_param = '') 
   {  
     $_SESSION['scriptcase']['sc_sql_ult_conexao'] = ''; 
     $str_where_filter = ('' != $str_where_param) ? ' and ' . $str_where_param : '';
     if (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_access))
     {
         $_SESSION['scriptcase']['sc_sql_ult_comando'] = "select max(item_proc_compra_id) from " . $this->Ini->nm_tabela . " where item_proc_compra_id < $this->item_proc_compra_id" . $str_where_filter; 
         $rs = $this->Db->Execute("select max(item_proc_compra_id) from " . $this->Ini->nm_tabela . " where item_proc_compra_id < $this->item_proc_compra_id" . $str_where_filter); 
     }  
     elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_mssql))
     {
         $_SESSION['scriptcase']['sc_sql_ult_comando'] = "select max(item_proc_compra_id) from " . $this->Ini->nm_tabela . " where item_proc_compra_id < $this->item_proc_compra_id" . $str_where_filter; 
         $rs = $this->Db->Execute("select max(item_proc_compra_id) from " . $this->Ini->nm_tabela . " where item_proc_compra_id < $this->item_proc_compra_id" . $str_where_filter); 
     }  
     elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_oracle))
     {
         $_SESSION['scriptcase']['sc_sql_ult_comando'] = "select max(item_proc_compra_id) from " . $this->Ini->nm_tabela . " where item_proc_compra_id < $this->item_proc_compra_id" . $str_where_filter; 
         $rs = $this->Db->Execute("select max(item_proc_compra_id) from " . $this->Ini->nm_tabela . " where item_proc_compra_id < $this->item_proc_compra_id" . $str_where_filter); 
     }  
     elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_informix))
     {
         $_SESSION['scriptcase']['sc_sql_ult_comando'] = "select max(item_proc_compra_id) from " . $this->Ini->nm_tabela . " where item_proc_compra_id < $this->item_proc_compra_id" . $str_where_filter; 
         $rs = $this->Db->Execute("select max(item_proc_compra_id) from " . $this->Ini->nm_tabela . " where item_proc_compra_id < $this->item_proc_compra_id" . $str_where_filter); 
     }  
     else  
     {
         $_SESSION['scriptcase']['sc_sql_ult_comando'] = "select max(item_proc_compra_id) from " . $this->Ini->nm_tabela . " where item_proc_compra_id < $this->item_proc_compra_id" . $str_where_filter; 
         $rs = $this->Db->Execute("select max(item_proc_compra_id) from " . $this->Ini->nm_tabela . " where item_proc_compra_id < $this->item_proc_compra_id" . $str_where_filter); 
     }  
     if ($rs === false && !$rs->EOF && $GLOBALS["NM_ERRO_IBASE"] != 1) 
     { 
         $this->Erro->mensagem (__FILE__, __LINE__, "banco", $this->Ini->Nm_lang['lang_errm_dber'], $this->Db->ErrorMsg()); 
         exit ; 
     }  
     if (isset($rs->fields[0]) && $rs->fields[0] != "") 
     { 
         $this->item_proc_compra_id = substr($this->Db->qstr($rs->fields[0]), 1, -1); 
         $rs->Close();  
         $this->nmgp_opcao = "igual";  
         return ;  
     } 
     else 
     { 
        $this->nmgp_opcao = "inicio";  
        $rs->Close();  
        return ; 
     } 
   } 
