function getDeParaSitCta($sitCta)
{
$_SESSION['scriptcase']['form_itens_proc_compra']['contr_erro'] = 'on';
  
    switch ($sitCta){
        case 'nao_embarcado':
            $vlPadrao ='1,2' ;
            break;
        case 'embarcado':
            $vlPadrao = '3,4,5';
            break;
        case 'entregue':
            $vlPadrao = '6,7,8,9';
            break;
    }
    $param = "cods_sit_$sitCta";
    $vlParam =  $this->buscarParametroIma($param,$vlPadrao);
    return $vlParam;


$_SESSION['scriptcase']['form_itens_proc_compra']['contr_erro'] = 'off';
}

