/*----- Scriptcase Locale: Internal Lib: distr_custo.php ------*/

function atualizarVlDespesaDistrCusto($idCtaCorrenCustoDistr, $valor)
{
$_SESSION['scriptcase']['form_itens_proc_compra']['contr_erro'] = 'on';
  
    $logAtualizado = 0;
    $id = $this->buscarDespesaContainerDistrCusto($idCtaCorrenCustoDistr);
    if($id <> 0){
        $logAtualizado = 1;
        $this->atualizarVlDespesaContainerPorId($id,$valor);
    }
    return $logAtualizado;

$_SESSION['scriptcase']['form_itens_proc_compra']['contr_erro'] = 'off';
}

