function logar($login,$pswd)
{
$_SESSION['scriptcase']['form_itens_proc_compra']['contr_erro'] = 'on';
  

    $vendLoja = 0;
    $aRet = $this->validarLogin($login,$pswd);
    $aUsuario = $aRet['array'];
    $erro = $aRet['erro'];

    if($erro == ''){
      $this->setarVarsLogin($aUsuario);
      $this->atualizarParametros();
    }

	return $erro;


$_SESSION['scriptcase']['form_itens_proc_compra']['contr_erro'] = 'off';
}

