function logarLDAP($usuario,$senha,$servidor='192.168.0.61',$dominio='IMA',$porta=389)
{
$_SESSION['scriptcase']['form_itens_proc_compra']['contr_erro'] = 'on';
  
    $ldapconn = ldap_connect("ldap://{$servidor}:{$porta}") ;

    if ($ldapconn) {
        $ldapbind = ldap_bind($ldapconn, "{$dominio}\\{$usuario}", $senha);
        if ($ldapbind) {
            return 'logado';
        }
        ldap_close($ldapconn);

    }
    return '';

$_SESSION['scriptcase']['form_itens_proc_compra']['contr_erro'] = 'off';
}

