function criarDiretorio($diretorio)
{
$_SESSION['scriptcase']['form_itens_proc_compra']['contr_erro'] = 'on';
  
    $retorno = 0;
    try{
        if($diretorio <> ''){
            mkdir($diretorio);
            $retorno = 1;
        }else{
            $retorno = "Diretorio informado em Branco";
        }
    }catch (Exception $e){
        $retorno = $e.getMessage();
    }
    return $retorno;

$_SESSION['scriptcase']['form_itens_proc_compra']['contr_erro'] = 'off';
}

