   function SC_fast_search($in_fields, $arg_search, $data_search)
   {
      $fields = (strpos($in_fields, "SC_all_Cmp") !== false) ? array("SC_all_Cmp") : explode(";", $in_fields);
      $this->NM_case_insensitive = true;
      if (empty($data_search)) 
      {
         unset($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['dyn_search_and_or']);
         unset($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['dyn_search_cache']);
          unset($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['where_filter']);
          unset($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['total']);
          unset($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['fast_search']);
          if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['where_detal']) && !empty($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['where_detal'])) 
          {
              $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['where_filter'] = $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['where_detal'];
          }
          if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['empty_filter']) && $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['empty_filter'])
          {
              unset($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['empty_filter']);
              $this->NM_ajax_info['empty_filter'] = 'ok';
              form_itens_proc_compra_pack_ajax_response();
              exit;
          }
          return;
      }
      $comando = "";
      if ($_SESSION['scriptcase']['charset'] != "UTF-8" && NM_is_utf8($data_search))
      {
          $data_search = NM_conv_charset($data_search, $_SESSION['scriptcase']['charset'], "UTF-8");
      }
      $sv_data = $data_search;
      foreach ($fields as $field) {
          if ($field == "SC_all_Cmp" || $field == "descricao") 
          {
              $this->SC_monta_condicao($comando, "descricao", $arg_search, $data_search, "VARCHAR", false);
          }
          if ($field == "SC_all_Cmp" || $field == "codigo_erp") 
          {
              $this->SC_monta_condicao($comando, "codigo_erp", $arg_search, $data_search, "VARCHAR", false);
          }
          if ($field == "SC_all_Cmp" || $field == "qt_dias_producao") 
          {
              $this->SC_monta_condicao($comando, "qt_dias_producao", $arg_search, str_replace(",", ".", $data_search), "INTEGER", false);
          }
          if ($field == "SC_all_Cmp" || $field == "unid_medida") 
          {
              $data_lookup = $this->SC_lookup_unid_medida($arg_search, $data_search);
              if (is_array($data_lookup) && !empty($data_lookup)) 
              {
                  $this->SC_monta_condicao($comando, "unid_medida", $arg_search, $data_lookup, "VARCHAR", false);
              }
          }
          if ($field == "SC_all_Cmp" || $field == "vl_custo_dolar") 
          {
              $this->SC_monta_condicao($comando, "vl_custo_dolar", $arg_search, str_replace(",", ".", $data_search), "NUMERIC", false);
          }
          if ($field == "SC_all_Cmp" || $field == "vl_base_tributacao") 
          {
              $this->SC_monta_condicao($comando, "vl_base_tributacao", $arg_search, str_replace(",", ".", $data_search), "NUMERIC", false);
          }
      }
      if ($this->NM_case_insensitive)
      {
          if (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_access))
          {
              $comando = str_replace("#lowerI#", "UCase(", $comando);
          }
          else
          {
              $comando = str_replace("#lowerI#", "Upper(", $comando);
           }
          $comando = str_replace("#lowerF#", ")", $comando);
      }
      else
      {
          $comando = str_replace("#lowerI#", "", $comando);
          $comando = str_replace("#lowerF#", "", $comando);
      }
      if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['where_detal']) && !empty($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['where_detal']) && !empty($comando)) 
      {
          $comando = $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['where_detal'] . " and (" .  $comando . ")";
      }
      if (empty($comando)) 
      {
          $comando = " 1 <> 1 "; 
      }
      if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['where_filter_form']) && '' != $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['where_filter_form'])
      {
          $sc_where = " where " . $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['where_filter_form'] . " and (" . $comando . ")";
      }
      else
      {
         $sc_where = " where " . $comando;
      }
      $nmgp_select = "SELECT count(*) AS countTest from " . $this->Ini->nm_tabela . $sc_where; 
      $_SESSION['scriptcase']['sc_sql_ult_comando'] = $nmgp_select; 
      $rt = $this->Db->Execute($nmgp_select) ; 
      if ($rt === false && !$rt->EOF && $GLOBALS["NM_ERRO_IBASE"] != 1) 
      { 
          $this->Erro->mensagem (__FILE__, __LINE__, "banco", $this->Ini->Nm_lang['lang_errm_dber'], $this->Db->ErrorMsg()); 
          exit ; 
      }  
      $qt_geral_reg_form_itens_proc_compra = isset($rt->fields[0]) ? $rt->fields[0] - 1 : 0; 
      $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['total'] = $qt_geral_reg_form_itens_proc_compra;
      $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['where_filter'] = $comando;
      $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['fast_search'][0] = $field;
      $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['fast_search'][1] = $arg_search;
      $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['fast_search'][2] = $sv_data;
      $rt->Close(); 
      if (isset($rt->fields[0]) && $rt->fields[0] > 0 &&  isset($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['empty_filter']) && $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['empty_filter'])
      {
          unset($_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['empty_filter']);
          $this->NM_ajax_info['empty_filter'] = 'ok';
          form_itens_proc_compra_pack_ajax_response();
          exit;
      }
      elseif (!isset($rt->fields[0]) || $rt->fields[0] == 0)
      {
          $_SESSION['sc_session'][$this->Ini->sc_page]['form_itens_proc_compra']['empty_filter'] = true;
          $this->NM_ajax_info['empty_filter'] = 'ok';
          form_itens_proc_compra_pack_ajax_response();
          exit;
      }
   }
